generated_pydough:
# Count exhibition records with attendance > 100 OR ticket price < 10
result = theme_gallery.CALCULATE(
    count_records = COUNT(
        exhibition_records.WHERE(
            (attendance > "100") |
            (exhibition.ticket_price < 10)
        )
    )
)

stadium_swimmer_counts = swimming.stadiums.CALCULATE(
    stadium_name=name,
    num_swimmers=NDISTINCT(events.records.swimmer.id)
)

stadiums_with_most_swimmers = stadium_swimmer_counts.CALCULATE(
    stadium_name=stadium_name,
    rank=RANKING(by=num_swimmers.DESC(), allow_ties=True)
).WHERE(
    rank == 1
).CALCULATE(
    stadium_name=stadium_name
)

result = country.CALCULATE(
    num_car_makers=COUNT(car_maker)
).WHERE(
    num_car_makers > 2
).CALCULATE(
    num_car_makers=num_car_makers
)

songs_with_lead_vocals = music_2.CALCULATE(
    song_count=COUNT(song.WHERE(HAS(vocal.WHERE(type == "lead")) == 1))
)

top_host_city_status = cities.WHERE(
    HAS(farm_competitions) == 1
).CALCULATE(
    city_status=status,
    num_competitions_hosted=COUNT(farm_competitions)
).TOP_K(1, by=num_competitions_hosted.DESC()).CALCULATE(
    status=city_status
)

avg_prices_by_manufacturer = manufactory_1.product.CALCULATE(
    manufacturer_name=manufacturer_join.name
).PARTITION(
    name="manufacturers_group",
    by=(manufacturer_name)
).CALCULATE(
    manufacturer_name=manufacturer_name,
    avg_product_price=AVG(product.price)
)

non_interacting_medicines = medicines.WHERE(
    HASNOT(medicine_enzyme_interactions.WHERE(enzyme.product == 'Heme')) == 1
).CALCULATE(
    medicine_name=name,
    trade_name=trade_name
)

states_with_mid_no_goalies = colleges.WHERE(
    (HAS(tryouts.WHERE(ppos == "mid")) == 1) &
    (HASNOT(tryouts.WHERE(ppos == "goalie")) == 1)
).PARTITION(
    name="unique_states",
    by=state
).CALCULATE(
    state_name=state
)

enzyme_activator_stats = medicine_enzyme_interactions.WHERE(
    interaction_type == 'activitor'
).PARTITION(
    name="enzyme_groups", by=(enzyme_id)
).CALCULATE(
    enzyme_identifier=enzyme_id,
    enzyme_full_name=medicine_enzyme_interactions.SINGULAR().enzyme.name,
    num_medicines_activated=COUNT(medicine_enzyme_interactions)
).TOP_K(1, by=num_medicines_activated.DESC())

most_activating_enzyme = enzyme_activator_stats.CALCULATE(
    enzyme_id=enzyme_identifier,
    enzyme_name=enzyme_full_name
)

# Filter cars with 8 cylinders or produced before 1980, then find max MPG
max_mpg_result = car_1.CALCULATE(
    max_mpg = MAX(cars_datas.WHERE(
        (cylinders == 8) | (year < 1980)
    ).mpg)
)

smallest_enrollment_per_state = colleges.PARTITION(
    name="states",
    by=(state)
).colleges.CALCULATE(
    rank_by_enrollment=RANKING(by=enr.ASC(), per="states")
).WHERE(
    rank_by_enrollment == 1
).CALCULATE(
    cname=cname,
    state=state,
    enr=enr
)

oldest_technician_starting_year = technicians.TOP_K(1, by=age.DESC()).CALCULATE(
    starting_year=starting_year
)

# Find customers who have used both "Close a policy" and "Upgrade a policy" services
customers_with_both_services = customer.WHERE(
    HAS(customers_policy.first_notification_of_losses.WHERE(
        service.service_name == "Close a policy"
    )) == 1
).WHERE(
    HAS(customers_policy.first_notification_of_losses.WHERE(
        service.service_name == "Upgrade a policy"
    )) == 1
).CALCULATE(customer_name=customer_name)
